const { seg, eo, lerp } = kit;

kit.scene('reduced-motion', {
  init(kit) {
    const markUrl = W.logoMarkUrl(kit);
    function panelMarkup(prefix, title, subtitle) {
      return '<div class="ui-window" style="width:820px;height:740px;padding:30px 32px;display:flex;flex-direction:column;gap:22px;position:relative">' +
        '<div style="display:flex;align-items:baseline;justify-content:space-between">' +
          '<h2 style="margin:0;font-size:24px;font-weight:700;color:var(--main)">' + title + '</h2>' +
          '<span style="font-size:15px;font-weight:600;color:var(--accent)">' + subtitle + '</span>' +
        '</div>' +
        '<div style="display:flex;gap:16px;align-items:center;padding:14px 16px;border-radius:10px;background:var(--nav-bg);position:relative;overflow:hidden;height:68px">' +
          '<div class="' + prefix + '-rail" style="width:44px;height:44px;border-radius:6px;display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0">' +
            '<img class="' + prefix + '-mark" src="' + markUrl + '" alt="Exam App mark" style="position:absolute;width:24px;height:24px"/>' +
            '<span class="' + prefix + '-glyph" style="position:absolute;display:flex;opacity:0">' + W.panelSvg() + '</span>' +
            '<div class="' + prefix + '-ring" style="position:absolute;inset:-4px;border:2px solid var(--accent);border-radius:9px;opacity:0"></div>' +
          '</div>' +
          '<div class="' + prefix + '-tip" style="padding:6px 12px;border-radius:6px;background:var(--main);color:var(--ground);font-size:14px;font-weight:600;opacity:0">Expand sidebar</div>' +
          '<span style="margin-left:auto;font-size:14px;color:var(--second)">Same-center swap + focus ring</span>' +
        '</div>' +
        '<div style="position:relative;height:140px;border-radius:10px;border:1px solid var(--hair);overflow:hidden;display:flex;background:var(--ground)">' +
          '<div class="' + prefix + '-drawer" style="width:220px;height:100%;background:var(--nav-bg);border-right:1px solid var(--hair);padding:14px;box-sizing:border-box;display:flex;flex-direction:column;gap:8px">' +
            '<div style="padding:8px 10px;border-radius:6px;background:var(--tint);font-size:14px;font-weight:600">DATAPREV · 2026</div>' +
            '<div style="font-size:13px;color:var(--main)">Changing competitions clears answers.</div>' +
          '</div>' +
          '<div style="flex:1;padding:18px;display:flex;flex-direction:column;justify-content:center;gap:6px">' +
            '<div style="font-size:15px;font-weight:600;color:var(--main)">Question context stays stationary</div>' +
            '<div style="font-size:14px;color:var(--second)">Overlay drawer &amp; answer-loss cue preserved</div>' +
          '</div>' +
        '</div>' +
        '<div style="padding:18px 20px;border-radius:10px;border:1px solid var(--hair);display:flex;flex-direction:column;gap:10px">' +
          '<div style="font-size:15px;font-weight:600;color:var(--main)">Answer feedback parity</div>' +
          '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-radius:6px;background:var(--ground)">' +
            '<span style="font-size:16px">B. GET</span>' +
            '<span class="' + prefix + '-corr" style="display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:700;color:var(--correct);opacity:0">' + W.checkSvg() + '<span>Correct</span></span>' +
          '</div>' +
          '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-radius:6px;background:var(--tint)">' +
            '<span style="font-size:16px">C. PATCH</span>' +
            '<span class="' + prefix + '-wrong" style="display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:700;color:var(--incorrect);opacity:0">' + W.crossSvg() + '<span>Your answer</span></span>' +
          '</div>' +
          '<div class="' + prefix + '-lock" style="display:flex;align-items:center;gap:14px;opacity:0">' +
            '<span style="font-size:16px;font-weight:700;color:var(--incorrect)">Incorrect answer</span>' +
            '<span style="font-size:14px;color:var(--second)">Answer locked</span>' +
          '</div>' +
        '</div>' +
      '</div>';
    }

    kit.stage.append(kit.h(
      '<div class="ground">' +
      W.studyChrome('5 · Reduced-Motion Alternative Parity', 'prefers-reduced-motion: reduce', 'Zero slide or scale · Identical state and feedback cues') +
      '<div style="position:absolute;left:110px;top:156px;display:flex;gap:60px">' +
        panelMarkup('rm-std', 'Standard motion', 'Eased slide + cross-fade') +
        panelMarkup('rm-red', 'prefers-reduced-motion', 'Instant state / opacity only') +
      '</div>' +
      '</div>'
    ));

    const bind = (p) => {
      const q = (s) => kit.stage.querySelector('.' + p + '-' + s);
      return {
        mark: q('mark'),
        glyph: q('glyph'),
        ring: q('ring'),
        tip: q('tip'),
        drawer: q('drawer'),
        corr: q('corr'),
        wrong: q('wrong'),
        lock: q('lock')
      };
    };
    this.std = bind('rm-std');
    this.red = bind('rm-red');
  },
  render(t) {
    // 1. Rail swap + focus ring
    const swapStd = eo(seg(t, 0.7, 1.1));
    this.std.mark.style.opacity = 1 - swapStd;
    this.std.glyph.style.opacity = swapStd;
    this.std.ring.style.opacity = swapStd;
    this.std.tip.style.opacity = swapStd;
    this.std.tip.style.transform = 'translateX(' + lerp(-10, 0, swapStd).toFixed(1) + 'px)';

    const swapRed = seg(t, 0.85, 0.98);
    this.red.mark.style.opacity = 1 - swapRed;
    this.red.glyph.style.opacity = swapRed;
    this.red.ring.style.opacity = swapRed;
    this.red.tip.style.opacity = swapRed;
    this.red.tip.style.transform = 'translateX(0px)';

    // 2. Drawer open: slide vs direct opacity
    const drwStd = eo(seg(t, 1.5, 2.0));
    this.std.drawer.style.transform = 'translateX(' + lerp(-220, 0, drwStd).toFixed(1) + 'px)';
    this.std.drawer.style.opacity = 1;

    const drwRed = seg(t, 1.7, 1.85);
    this.red.drawer.style.transform = 'translateX(0px)';
    this.red.drawer.style.opacity = drwRed;

    // 3. Feedback arrival: lifted fade vs direct opacity
    const fbStd = eo(seg(t, 2.5, 2.95));
    this.std.corr.style.opacity = fbStd;
    this.std.wrong.style.opacity = fbStd;
    this.std.lock.style.opacity = fbStd;
    this.std.lock.style.transform = 'translateY(' + lerp(8, 0, fbStd).toFixed(1) + 'px)';

    const fbRed = seg(t, 2.7, 2.85);
    this.red.corr.style.opacity = fbRed;
    this.red.wrong.style.opacity = fbRed;
    this.red.lock.style.opacity = fbRed;
    this.red.lock.style.transform = 'translateY(0px)';
  }
});
